from fastapi import APIRouter, Depends, HTTPException, Request, status
from sqlalchemy.orm import Session

from src.backend.db.session import get_db
from src.backend.core.deps import get_current_user
from src.backend.services.auth_service import login, refresh_access_token, logout
from src.backend.schemas.auth import (
    LoginRequest,
    RefreshRequest,
    TokenResponse,
    AccessTokenResponse,
    MessageResponse,
    UserPublic,
)
from src.backend.models.user import User


router = APIRouter(prefix="/api/auth", tags=["auth"])


def get_client_info(request: Request) -> tuple[str | None, str | None]:
    ip_address = request.client.host if request.client else None
    user_agent = request.headers.get("user-agent")
    return ip_address, user_agent


@router.post("/login", response_model=TokenResponse)
def auth_login(
    request: Request,
    body: LoginRequest,
    db: Session = Depends(get_db),
):
    ip_address, user_agent = get_client_info(request)
    result = login(db, body.email, body.password, ip_address, user_agent)
    if not result:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    return result


@router.post("/refresh", response_model=AccessTokenResponse)
def auth_refresh(
    body: RefreshRequest,
    db: Session = Depends(get_db),
):
    result = refresh_access_token(db, body.refresh_token)
    if not result:
        raise HTTPException(status_code=401, detail="Invalid or expired refresh token")
    return result


@router.post("/logout", response_model=MessageResponse)
def auth_logout(
    request: Request,
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    auth_header = request.headers.get("authorization", "")
    if not auth_header.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid authorization header")

    access_token = auth_header.split(" ", 1)[1]

    from src.backend.core.security import decode_token
    payload = decode_token(access_token)
    if payload.get("type") != "access":
        raise HTTPException(status_code=401, detail="Invalid token type")

    user_id_str = payload.get("sub")
    if not user_id_str:
        raise HTTPException(status_code=401, detail="Invalid token payload")

    refresh_token = payload.get("refresh_token", "")
    ip_address, user_agent = get_client_info(request)

    success = logout(db, refresh_token, ip_address, user_agent)
    if not success:
        raise HTTPException(status_code=401, detail="Could not revoke session")

    return MessageResponse(message="Logged out successfully")


@router.get("/me", response_model=UserPublic)
def auth_me(
    current_user: User = Depends(get_current_user),
):
    return UserPublic.model_validate(current_user)

