import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.boq import (
    BOQItemListResponse,
    BOQItemRead,
    BOQListResponse,
    BOQRead,
)
from src.backend.services.boq_service import (
    get_boq_detail,
    get_boq_items,
    list_boq_versions,
    soft_delete_boq_service,
)

router = APIRouter(prefix="/api", tags=["boqs"])


@router.get("/projects/{project_id}/boqs", response_model=BOQListResponse)
def list_project_boqs(
    project_id: uuid.UUID,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> BOQListResponse:
    items, total, page, page_size = list_boq_versions(
        db, project_id, page=page, page_size=page_size
    )
    return BOQListResponse(
        items=[BOQRead(**item) for item in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.get("/boqs/{boq_id}", response_model=BOQRead)
def get_boq(
    boq_id: uuid.UUID,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
) -> BOQRead:
    result = get_boq_detail(db, boq_id)
    if not result:
        raise HTTPException(status_code=404, detail="BOQ not found")
    return BOQRead(**result)


@router.get("/boqs/{boq_id}/items", response_model=BOQItemListResponse)
def get_boq_items(
    boq_id: uuid.UUID,
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> BOQItemListResponse:
    items, total, page, page_size = get_boq_items(
        db, boq_id, page=page, page_size=page_size
    )
    return BOQItemListResponse(
        items=[BOQItemRead(**item) for item in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.delete("/boqs/{boq_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_boq(
    boq_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.ADMIN)),
    db: Session = Depends(get_db),
) -> None:
    success = soft_delete_boq_service(db, boq_id, current_user.id)
    if not success:
        raise HTTPException(status_code=404, detail="BOQ not found")

