import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";

export function useBOQs(projectId: string, page = 1, pageSize = 20) {
  return useQuery({
    queryKey: ["boqs", projectId, page, pageSize],
    queryFn: () => api.listBOQs(projectId, { page, page_size: pageSize }),
  });
}

export function useBOQ(projectId: string, boqId: string) {
  return useQuery({
    queryKey: ["boq", projectId, boqId],
    queryFn: () => api.getBOQ(projectId, boqId),
  });
}

export function useBOQItems(projectId: string, boqId: string, page = 1, pageSize = 50) {
  return useQuery({
    queryKey: ["boqItems", projectId, boqId, page, pageSize],
    queryFn: () => api.getBOQItems(projectId, boqId, { page, page_size: pageSize }),
  });
}

export function useDeleteBOQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, boqId }: { projectId: string; boqId: string }) =>
      api.deleteBOQ(projectId, boqId),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["boqs", variables.projectId] });
    },
  });
}

export function useUploadBOQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, file, notes }: { projectId: string; file: File; notes?: string }) =>
      api.uploadBOQ(projectId, file, notes),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["boqs", variables.projectId] });
    },
  });
}

import { useState } from "react";
import { useBOQItems } from "@/hooks/useBoqs";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowLeft, ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";

interface BOQItemTableProps {
  projectId: string;
  boqId: string;
}

export function BOQItemTable({ projectId, boqId }: BOQItemTableProps) {
  const [page, setPage] = useState(1);
  const [categoryFilter, setCategoryFilter] = useState("");
  const pageSize = 50;
  const { data, isLoading } = useBOQItems(projectId, boqId, page, pageSize);

  const items = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);
  const categories = [...new Set(items.map((i) => i.category).filter(Boolean))];

  return (
    <Card>
      <CardHeader className="flex-row items-center justify-between">
        <CardTitle>BOQ Line Items</CardTitle>
        <select
          className="border rounded px-2 py-1 text-sm"
          value={categoryFilter}
          onChange={(e) => { setCategoryFilter(e.target.value); setPage(1); }}
        >
          <option value="">All Categories</option>
          {categories.map((c) => (
            <option key={c as string} value={c as string}>{c}</option>
          ))}
        </select>
      </CardHeader>
      <CardContent>
        <div className="rounded-md border overflow-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Line</TableHead>
                <TableHead>Category</TableHead>
                <TableHead>Description</TableHead>
                <TableHead>Spec</TableHead>
                <TableHead>Unit</TableHead>
                <TableHead className="text-right">Qty</TableHead>
                <TableHead className="text-right">Rate</TableHead>
                <TableHead className="text-right">Amount</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={8} className="text-center">Loading...</TableCell>
                </TableRow>
              ) : items.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} className="text-center">No items found</TableCell>
                </TableRow>
              ) : (
                (categoryFilter ? items.filter((i) => i.category === categoryFilter) : items).map((item) => (
                  <TableRow key={item.id}>
                    <TableCell className="font-mono text-sm">{item.line_number}</TableCell>
                    <TableCell>{item.category ?? "—"}</TableCell>
                    <TableCell>{item.description}</TableCell>
                    <TableCell>{item.specification ?? "—"}</TableCell>
                    <TableCell>{item.unit}</TableCell>
                    <TableCell className="text-right">{item.quantity}</TableCell>
                    <TableCell className="text-right">₹{item.rate.toLocaleString()}</TableCell>
                    <TableCell className="text-right">₹{item.amount.toLocaleString()}</TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
        <div className="flex items-center justify-between mt-4">
          <span className="text-sm text-muted-foreground">{total} item(s)</span>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <span className="text-sm">Page {page} of {totalPages}</span>
            <Button variant="outline" size="sm" onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={page >= totalPages}>
              <ArrowRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

