import { Task, TaskPriority } from "@/types/api";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Calendar, AlertTriangle } from "lucide-react";

const PRIORITY_COLORS: Record<TaskPriority, string> = {
  low: "bg-gray-100 text-gray-700",
  medium: "bg-yellow-100 text-yellow-800",
  high: "bg-orange-100 text-orange-800",
  critical: "bg-red-100 text-red-800",
};

interface TaskCardProps {
  task: Task;
  onClick: () => void;
  isBlocked?: boolean;
  blockedByCount?: number;
}

export function TaskCard({ task, onClick, isBlocked, blockedByCount = 0 }: TaskCardProps) {
  const isOverdue = task.due_date && new Date(task.due_date) < new Date() && task.status !== "done";

  return (
    <Card
      className={`cursor-pointer hover:shadow-md transition-shadow ${isBlocked ? "opacity-75 border-l-4 border-l-orange-400" : ""}`}
      onClick={onClick}
    >
      <CardContent className="p-3 space-y-2">
        <div className="flex items-start justify-between gap-2">
          <span className="font-medium text-sm leading-tight line-clamp-2">{task.title}</span>
          <Badge className={`shrink-0 text-xs ${PRIORITY_COLORS[task.priority]}`}>
            {task.priority}
          </Badge>
        </div>

        {task.subtask_count > 0 && (
          <div className="text-xs text-muted-foreground">
            {task.subtask_count} subtask{task.subtask_count !== 1 ? "s" : ""}
          </div>
        )}

        {isBlocked && blockedByCount > 0 && (
          <div className="flex items-center gap-1 text-xs text-orange-600">
            <AlertTriangle className="h-3 w-3" />
            Blocked by {blockedByCount} task{blockedByCount !== 1 ? "s" : ""}
          </div>
        )}

        <div className="flex items-center justify-between">
          {task.assignee_name ? (
            <span className="text-xs text-muted-foreground truncate max-w-[100px]">{task.assignee_name}</span>
          ) : (
            <span className="text-xs text-muted-foreground">Unassigned</span>
          )}
          {task.due_date && (
            <div className={`flex items-center gap-1 text-xs ${isOverdue ? "text-red-600" : "text-muted-foreground"}`}>
              <Calendar className="h-3 w-3" />
              {new Date(task.due_date).toLocaleDateString()}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Task, TaskPriority, TaskStatus } from "@/types/api";

interface TaskFormProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (data: Partial<Task>) => void;
  initialData?: Partial<Task>;
  isPending?: boolean;
  mode: "create" | "edit";
}

export function TaskForm({ open, onOpenChange, onSubmit, initialData, isPending, mode }: TaskFormProps) {
  const [title, setTitle] = useState(initialData?.title ?? "");
  const [description, setDescription] = useState(initialData?.description ?? "");
  const [priority, setPriority] = useState<TaskPriority>(initialData?.priority ?? "medium");
  const [status, setStatus] = useState<TaskStatus>(initialData?.status ?? "todo");
  const [assigneeId, setAssigneeId] = useState(initialData?.assignee_id ?? "");
  const [dueDate, setDueDate] = useState(initialData?.due_date?.split("T")[0] ?? "");
  const [estimatedHours, setEstimatedHours] = useState(
    initialData?.estimated_hours?.toString() ?? ""
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({
      title: title.trim(),
      description: description.trim() || null,
      priority,
      status,
      assignee_id: assigneeId || null,
      due_date: dueDate ? `${dueDate}T00:00:00` : null,
      estimated_hours: estimatedHours ? parseFloat(estimatedHours) : null,
    });
    if (mode === "create") {
      setTitle("");
      setDescription("");
      setPriority("medium");
      setStatus("todo");
      setAssigneeId("");
      setDueDate("");
      setEstimatedHours("");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>{mode === "create" ? "Create Task" : "Edit Task"}</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="title">Title *</Label>
            <Input
              id="title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Task title"
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Task description (optional)"
              rows={3}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Priority</Label>
              <Select value={priority} onValueChange={(v) => setPriority(v as TaskPriority)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="critical">Critical</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={status} onValueChange={(v) => setStatus(v as TaskStatus)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todo">Todo</SelectItem>
                  <SelectItem value="in_progress">In Progress</SelectItem>
                  <SelectItem value="blocked">Blocked</SelectItem>
                  <SelectItem value="done">Done</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="space-y-2">
            <Label htmlFor="assignee">Assignee</Label>
            <Input
              id="assignee"
              value={assigneeId}
              onChange={(e) => setAssigneeId(e.target.value)}
              placeholder="Assignee user ID (leave blank to unassign)"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="due_date">Due Date</Label>
              <Input
                id="due_date"
                type="date"
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="estimated_hours">Estimated Hours</Label>
              <Input
                id="estimated_hours"
                type="number"
                min="0"
                step="0.5"
                value={estimatedHours}
                onChange={(e) => setEstimatedHours(e.target.value)}
                placeholder="0"
              />
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={!title.trim() || isPending}>
              {isPending ? "Saving..." : mode === "create" ? "Create" : "Save"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { Task, TaskStatus, TaskPriority } from "@/types/api";
import {
  useTransitionTaskStatus,
  useUpdateTask,
  useRemoveTaskDependency,
} from "@/hooks/useTasks";
import { AlertTriangle, Clock, User, Calendar, Link2, ListChecks } from "lucide-react";

const STATUS_LABELS: Record<TaskStatus, string> = {
  todo: "Todo",
  in_progress: "In Progress",
  blocked: "Blocked",
  done: "Done",
};

const PRIORITY_COLORS: Record<TaskPriority, string> = {
  low: "bg-gray-100 text-gray-700",
  medium: "bg-yellow-100 text-yellow-800",
  high: "bg-orange-100 text-orange-800",
  critical: "bg-red-100 text-red-800",
};

interface TaskDetailProps {
  task: Task | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDeleted?: () => void;
}

const NEXT_STATUSES: Record<TaskStatus, TaskStatus[]> = {
  todo: ["in_progress"],
  in_progress: ["done", "blocked"],
  blocked: ["in_progress"],
  done: ["in_progress"],
};

export function TaskDetail({ task, open, onOpenChange, onDeleted }: TaskDetailProps) {
  const [confirmDelete, setConfirmDelete] = useState(false);

  const transitionMutation = useTransitionTaskStatus();
  const updateMutation = useUpdateTask();
  const deleteMutation = useRemoveTaskDependency();

  if (!task) return null;

  const allowedNextStatuses = NEXT_STATUSES[task.status] ?? [];
  const hasBlockedDeps = task.blocked_by.some((d) => d.depends_on_status !== "done");
  const isStartBlocked = task.status === "todo" && hasBlockedDeps;

  const handleTransition = async (toStatus: TaskStatus) => {
    if (isStartBlocked && toStatus === "in_progress") return;
    await transitionMutation.mutateAsync({ taskId: task.id, status: toStatus });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3">
            {task.title}
            <Badge className={PRIORITY_COLORS[task.priority]}>{task.priority}</Badge>
            <Badge variant="outline">{STATUS_LABELS[task.status]}</Badge>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {task.description && (
            <div>
              <Label className="text-muted-foreground">Description</Label>
              <p className="mt-1 text-sm whitespace-pre-wrap">{task.description}</p>
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div className="flex items-center gap-2">
              <User className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm">
                {task.assignee_name ?? "Unassigned"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm">
                {task.due_date ? new Date(task.due_date).toLocaleDateString() : "No due date"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Clock className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm">
                Est: {task.estimated_hours ?? "—"}h · Actual: {task.actual_hours ?? "—"}h
              </span>
            </div>
            <div className="flex items-center gap-2">
              <User className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">
                Created by {task.created_by_name ?? task.created_by}
              </span>
            </div>
          </div>

          {isStartBlocked && (
            <div className="flex items-center gap-2 p-3 rounded bg-orange-50 border border-orange-200 text-orange-800">
              <AlertTriangle className="h-4 w-4 shrink-0" />
              <span className="text-sm">
                This task is blocked by {task.blocked_by.length} incomplete task
                {task.blocked_by.length !== 1 ? "s" : ""}
              </span>
            </div>
          )}

          <Separator />

          <div>
            <Label className="text-muted-foreground flex items-center gap-2 mb-2">
              <Link2 className="h-4 w-4" />
              Blocked By
            </Label>
            {task.blocked_by.length === 0 ? (
              <p className="text-sm text-muted-foreground">No dependencies</p>
            ) : (
              <div className="space-y-2">
                {task.blocked_by.map((dep) => (
                  <div key={dep.id} className="flex items-center justify-between p-2 rounded bg-muted">
                    <div className="flex items-center gap-2">
                      <Badge variant="outline">{dep.depends_on_status}</Badge>
                      <span className="text-sm">{dep.depends_on_title}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div>
            <Label className="text-muted-foreground flex items-center gap-2 mb-2">
              <ListChecks className="h-4 w-4" />
              Blocks ({task.blocks.length})
            </Label>
            {task.blocks.length === 0 ? (
              <p className="text-sm text-muted-foreground">Does not block any tasks</p>
            ) : (
              <div className="space-y-1">
                {task.blocks.map((dep) => (
                  <div key={dep.id} className="text-sm text-muted-foreground">
                    → {dep.depends_on_title}
                  </div>
                ))}
              </div>
            )}
          </div>

          <Separator />

          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm text-muted-foreground">Move to:</span>
            {allowedNextStatuses.map((s) => (
              <Button
                key={s}
                size="sm"
                variant="outline"
                disabled={
                  (s === "in_progress" && isStartBlocked) ||
                  transitionMutation.isPending
                }
                onClick={() => handleTransition(s)}
              >
                {STATUS_LABELS[s]}
              </Button>
            ))}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

