import { useState, useMemo } from "react";
import { useTasks, useCreateTask } from "@/hooks/useTasks";
import { TaskCard } from "./TaskCard";
import { TaskDetail } from "./TaskDetail";
import { TaskForm } from "./TaskForm";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Plus, Filter } from "lucide-react";
import type { Task, TaskStatus, TaskPriority } from "@/types/api";

const COLUMNS: { id: TaskStatus; label: string }[] = [
  { id: "todo", label: "Todo" },
  { id: "in_progress", label: "In Progress" },
  { id: "blocked", label: "Blocked" },
  { id: "done", label: "Done" },
];

interface TaskKanbanProps {
  projectId: string;
}

export function TaskKanban({ projectId }: TaskKanbanProps) {
  const [page] = useState(1);
  const [pageSize] = useState(100);
  const [priorityFilter, setPriorityFilter] = useState<string>("");
  const [assigneeFilter, setAssigneeFilter] = useState<string>("");
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  const params = useMemo(() => ({
    page,
    page_size: pageSize,
    ...(priorityFilter && { priority: priorityFilter }),
    ...(assigneeFilter && { assignee_id: assigneeFilter }),
  }), [page, pageSize, priorityFilter, assigneeFilter]);

  const { data, isLoading } = useTasks(projectId, params);
  const createMutation = useCreateTask();

  const tasks = data?.items ?? [];

  const tasksByStatus = useMemo(() => {
    const map: Record<TaskStatus, Task[]> = { todo: [], in_progress: [], blocked: [], done: [] };
    for (const t of tasks) {
      if (map[t.status]) map[t.status].push(t);
    }
    return map;
  }, [tasks]);

  const handleCreate = async (data: Partial<Task>) => {
    await createMutation.mutateAsync({ projectId, data });
    setShowForm(false);
  };

  const handleCardClick = (task: Task) => {
    setSelectedTask(task);
  };

  const handleFormOpenChange = (open: boolean) => {
    setShowForm(open);
    if (!open) setEditingTask(null);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-2">
            <Filter className="h-4 w-4 text-muted-foreground" />
            <Select value={priorityFilter} onValueChange={setPriorityFilter}>
              <SelectTrigger className="w-[130px]">
                <SelectValue placeholder="Priority" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Priorities</SelectItem>
                <SelectItem value="low">Low</SelectItem>
                <SelectItem value="medium">Medium</SelectItem>
                <SelectItem value="high">High</SelectItem>
                <SelectItem value="critical">Critical</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="flex items-center gap-2">
            <Input
              placeholder="Assignee ID..."
              className="w-[140px]"
              value={assigneeFilter}
              onChange={(e) => setAssigneeFilter(e.target.value)}
            />
          </div>
        </div>
        <Button onClick={() => setShowForm(true)}>
          <Plus className="h-4 w-4 mr-1" />
          New Task
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {COLUMNS.map((col) => {
          const colTasks = tasksByStatus[col.id] ?? [];
          return (
            <div key={col.id} className="space-y-2">
              <div className="flex items-center justify-between px-1">
                <h3 className="font-semibold text-sm">{col.label}</h3>
                <span className="text-xs text-muted-foreground bg-muted rounded-full px-2 py-0.5">
                  {colTasks.length}
                </span>
              </div>
              <div className="space-y-2 min-h-[100px]">
                {isLoading ? (
                  <p className="text-sm text-muted-foreground p-2">Loading...</p>
                ) : colTasks.length === 0 ? (
                  <p className="text-sm text-muted-foreground p-2">No tasks</p>
                ) : (
                  colTasks.map((task) => (
                    <TaskCard
                      key={task.id}
                      task={task}
                      onClick={() => handleCardClick(task)}
                      isBlocked={col.id === "blocked"}
                      blockedByCount={task.blocked_by.length}
                    />
                  ))
                )}
              </div>
            </div>
          );
        })}
      </div>

      <TaskDetail
        task={selectedTask}
        open={!!selectedTask}
        onOpenChange={(open) => { if (!open) setSelectedTask(null); }}
      />

      <TaskForm
        open={showForm}
        onOpenChange={handleFormOpenChange}
        onSubmit={handleCreate}
        isPending={createMutation.isPending}
        mode="create"
      />
    </div>
  );
}

import { useState } from "react";
import { useMyTasks } from "@/hooks/useTasks";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowUpDown, Calendar, AlertTriangle } from "lucide-react";
import type { TaskPriority, TaskStatus } from "@/types/api";

const PRIORITY_COLORS: Record<TaskPriority, string> = {
  low: "bg-gray-100 text-gray-700",
  medium: "bg-yellow-100 text-yellow-800",
  high: "bg-orange-100 text-orange-800",
  critical: "bg-red-100 text-red-800",
};

const STATUS_LABELS: Record<TaskStatus, string> = {
  todo: "Todo",
  in_progress: "In Progress",
  blocked: "Blocked",
  done: "Done",
};

const PRIORITY_ORDER: Record<TaskPriority, number> = {
  critical: 0,
  high: 1,
  medium: 2,
  low: 3,
};

export function MyTasksPage() {
  const [sortBy, setSortBy] = useState<"due_date" | "priority">("due_date");
  const { data, isLoading } = useMyTasks({ page_size: 100 });

  const tasks = data?.items ?? [];

  const sorted = [...tasks].sort((a, b) => {
    if (sortBy === "due_date") {
      if (!a.due_date && !b.due_date) return 0;
      if (!a.due_date) return 1;
      if (!b.due_date) return -1;
      return new Date(a.due_date).getTime() - new Date(b.due_date).getTime();
    }
    return (PRIORITY_ORDER[a.priority] ?? 99) - (PRIORITY_ORDER[b.priority] ?? 99);
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">My Tasks</h1>
        <p className="text-muted-foreground">
          All tasks assigned to you across projects
        </p>
      </div>

      <div className="flex items-center gap-2">
        <span className="text-sm text-muted-foreground">Sort by:</span>
        <Button
          variant={sortBy === "due_date" ? "secondary" : "outline"}
          size="sm"
          onClick={() => setSortBy("due_date")}
        >
          <Calendar className="h-4 w-4 mr-1" />
          Due Date
        </Button>
        <Button
          variant={sortBy === "priority" ? "secondary" : "outline"}
          size="sm"
          onClick={() => setSortBy("priority")}
        >
          <ArrowUpDown className="h-4 w-4 mr-1" />
          Priority
        </Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>
            {tasks.length} task{tasks.length !== 1 ? "s" : ""} assigned to you
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="rounded-md border overflow-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Title</TableHead>
                  <TableHead>Priority</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Due Date</TableHead>
                  <TableHead>Project</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  <TableRow>
                    <TableCell colSpan={5} className="text-center">Loading...</TableCell>
                  </TableRow>
                ) : sorted.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} className="text-center text-muted-foreground">
                      No tasks assigned to you
                    </TableCell>
                  </TableRow>
                ) : (
                  sorted.map((task) => {
                    const isOverdue = task.due_date && new Date(task.due_date) < new Date() && task.status !== "done";
                    return (
                      <TableRow key={task.id}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            {task.status === "blocked" && (
                              <AlertTriangle className="h-4 w-4 text-orange-500 shrink-0" />
                            )}
                            <span className="font-medium">{task.title}</span>
                            {task.subtask_count > 0 && (
                              <span className="text-xs text-muted-foreground">
                                ({task.subtask_count} subtasks)
                              </span>
                            )}
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge className={PRIORITY_COLORS[task.priority]}>
                            {task.priority}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline">{STATUS_LABELS[task.status]}</Badge>
                        </TableCell>
                        <TableCell className={isOverdue ? "text-red-600" : ""}>
                          {task.due_date
                            ? new Date(task.due_date).toLocaleDateString()
                            : "—"}
                        </TableCell>
                        <TableCell className="text-muted-foreground text-sm">
                          {task.project_id}
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

